import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

const specPath = "week1/generated/day3-smoke.spec.ts";

await writeProjectFile(specPath, `
// Week 1, Day 3 — a trivial smoke spec, written just to give the CLI commands
// (npx playwright test, --headed, show-report) something real to run against.
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Day 3 smoke", () => {
  test("the login page loads with an email field", async ({ page }) => {
    await page.goto("/");
    await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
  });

  test("valid credentials reach the dashboard", async ({ page }) => {
    await loginAs(page);
    await expect(page).toHaveURL(/dashboard/);
  });
});
`.trim());

await runSpec(specPath);

// The use block, as plain data, so the shape is visible without opening the file.
const useBlock = {
  baseURL: "https://test-automation-banking.vercel.app",
  trace: "retain-on-failure",
  screenshot: "only-on-failure",
  video: "retain-on-failure",
};
console.log(JSON.stringify(useBlock, null, 2));
